<?php require 'bootstrap.php';require 'layout.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$id=(int)($_POST['product_id']??0);$action=$_POST['action']??'';if($action==='clear'){$_SESSION['cart']=[];}elseif($action==='remove'){unset($_SESSION['cart'][$id]);}elseif($action==='add'){ $s=db()->prepare('SELECT stock FROM products WHERE id=? AND is_active=1');$s->execute([$id]);$stock=$s->fetchColumn();if($stock===false)throw new RuntimeException('Product unavailable');$qty=(int)($_SESSION['cart'][$id]??0);if($qty+1>(int)$stock)throw new RuntimeException('Not enough stock');$_SESSION['cart'][$id]=$qty+1;}redirect('cart.php');}catch(Throwable $e){$error=$e->getMessage();}}$cart=$_SESSION['cart']??[];$items=[];$total=0;if($cart){$ids=array_keys($cart);$place=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT * FROM products WHERE id IN ($place)");$s->execute($ids);$items=$s->fetchAll();foreach($items as $i)$total+=(float)$i['price']*$cart[$i['id']];}head_html('Cart');?><h1>Your cart</h1><?php if($error):?><p class="alert"><?=e($error)?></p><?php endif;?><?php if(!$items):?><p>Cart is empty. <a class="accent" href="index.php">Browse parts →</a></p><?php else:?><div class="panel"><table class="table"><tr><th>Item</th><th>Qty</th><th>Subtotal</th><th></th></tr><?php foreach($items as $i):?><tr><td><?=e($i['name'])?></td><td><?=$cart[$i['id']]?></td><td>₱<?=number_format($i['price']*$cart[$i['id']],2)?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="product_id" value="<?=$i['id']?>"><button class="btn alt" name="action" value="remove">Remove</button></form></td></tr><?php endforeach;?></table><h2>Total: ₱<?=number_format($total,2)?></h2><a class="btn" href="checkout.php">Checkout →</a></div><?php endif;foot_html();